use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs: Vec<i64> = match input["jobs"].as_array().unwrap() {
        [job1, job2, job3] => vec![job1, job2, job3],
        _ => panic!("Input must contain three jobs"),
    };

    let quantum: i64 = match input["quantum"].as_i64().unwrap() {
        q if q > 0 => q,
        _ => panic!("Input must contain a positive quantum"),
    };

    let mut jobs_done = vec![0; jobs.len()];
    let mut jobs_left = jobs.clone();
    let mut current_turn = 0;

    while jobs_left.len() > 0 {
        let job = jobs_left.remove(0);
        let job_turn = current_turn + job as usize;

        if jobs_done[job_turn] == 0 {
            jobs_done[job_turn] = 1;
            jobs_left.remove(job_turn);
        }

        current_turn += 1;

        if current_turn >= quantum {
            current_turn = 0;
        }
    }

    let mut result = vec![];
    for i in 0..jobs.len() {
        if jobs_done[i] == 1 {
            result.push(i);
        }
    }

    json!(result)
}
